18	/**
19	 * Everyone the three sources below name, with what kind of account each one is.
20	 *
21	 * Exported for the callers that need both answers from one read: the result comment
22	 * escapes against every participant and asks separately which of them the run
23	 * called, and reading the three endpoints twice to answer two questions about the
24	 * same list is two answers waiting to disagree.
25	 *
26	 * Three sources, each best-effort and each read separately so a failure of one
27	 * does not take the others with it:
28	 *
29	 *   - whoever opened the issue or pull request
30	 *   - whoever has commented on it
31	 *   - the repository's collaborators
32	 *
33	 * The `issues` endpoint rather than `gh issue view`, because a pull request is an
34	 * issue to that endpoint and is not to that command -- one call that works for
35	 * both beats two that each work for half.
36	 *
37	 * An empty result is the fail-closed case and is correct: nothing confirmed means
38	 * nothing is exempt, and `domain/work/mention.ts` explains why that is the cheaper of
39	 * the two mistakes.
40	 *
41	 * A login named by one source as a bot and by another as a person counts as a
42	 * person. The two readings disagree only for an account somebody registered twice,
43	 * and the direction that keeps the account callable is the one that does not turn a
44	 * person's own login into a silent failure.
45	 */
46	export function participantAccounts(repo: string, number: string | number): Participant[] {
47	  if (!repo || !String(number).trim()) return [];
48	  const found = new Map<string, boolean>();
49	
50	  const record = (login: string | undefined, bot: boolean): void => {
51	    if (typeof login !== "string" || !login) return;
52	    const seen = found.get(login);
53	    // Bot only while every source that named it says bot -- see above.
54	    found.set(login, (seen ?? true) && bot);
55	  };
56	
57	  const collect = (args: string[], read: (json: unknown) => unknown[]) => {
58	    const { code, stdout } = gh(...args);
59	    if (code !== 0) return;
60	    try {
61	      for (const person of read(JSON.parse(stdout))) {
62	        const { login, bot } = person as { login?: unknown; bot?: unknown };
63	        record(typeof login === "string" ? login : undefined, bot === true);
64	      }
65	    } catch {
66	      // A body that will not parse tells us nothing about who may be mentioned.
67	    }
68	  };
69	
70	  collect(["api", `repos/${repo}/issues/${number}`], (json) => {
71	    const issue = json as { user?: { login?: string; type?: string } };
72	    return issue.user ? [{ login: issue.user.login, bot: issue.user.type === "Bot" }] : [];
73	  });
74	  // The thread, through the shared `listComments` -- one read for every comment list
75	  // in the repository. This used to run `--paginate` and then `JSON.parse` the whole
76	  // stdout, which throws from the second page on: a node past 100 comments answered
77	  // with none of its commenters, silently. A failed read is still "nobody learned",
78	  // which is this module's fail-closed answer.
79	  try {
80	    for (const comment of listComments(repo, number)) {
81	      record(comment.user?.login, comment.user?.type === "Bot");
82	    }
83	  } catch {
84	    // Same as a failed read above: nothing confirmed, so nothing exempt.
85	  }
86	  collect(["api", `repos/${repo}/collaborators`, "--paginate"], (json) =>
87	    (json as { login?: string; type?: string }[]).map((person) => ({
88	      login: person.login,
89	      bot: person.type === "Bot",
90	    })),
91	  );
92	
93	  return [...found].map(([login, bot]) => ({ login, bot }));
94	}
95	
96	/** Everyone an agent may mention from a thread without notifying a stranger. */
97	export function knownParticipants(repo: string, number: string | number): string[] {
98	  return participantAccounts(repo, number).map((person) => person.login);
99	}
100	
101	/**
102	 * The people a run may hand the work to, by login.
103	 *
104	 * A bot is not one of them: `@dependabot` and the machinery's own accounts are in
105	 * the participant list, notify nobody who can decide anything, and are not a way to
106	 * end a turn — see `domain/work/ending-calls.ts`. Filtering here rather than there
107	 * keeps the answer to "may this be pinged" and the answer to "is this somebody's
108	 * turn" reading the same list of accounts.
109	 */
110	export function humanParticipants(repo: string, number: string | number): string[] {
111	  return participantAccounts(repo, number)
112	    .filter((person) => !person.bot)
113	    .map((person) => person.login);
114	}

